sqlMap.select:
SELECT T.DEPTNO, T.ORG_NAME_LOCAL, T.DEPT_LEVEL, T.DEPT_DISTINGUISH_STANDARD, T.DEPT_DISTINGUISH_STANDARD_TWO, T.DEPT_DISTINGUISH_THREE, T.PARENT_DEPT_NO, (SELECT COUNT(1) FROM HR_EMPLOYEE WHERE DEPTNO = T.DEPTNO AND CPNY_ID = #interCpnyID#) CNT FROM (SELECT distinct OI.CPNY_ID, OI.ORDERNO, OI.DEPTNO, OI.ORG_NAME_LOCAL, OI.DEPT_LEVEL, OI.PARENT_DEPT_NO, nvl(OIT.DEPT_DISTINGUISH_STANDARD,'0') DEPT_DISTINGUISH_STANDARD, nvl(OIT.DEPT_DISTINGUISH_STANDARD_TWO,'0') DEPT_DISTINGUISH_STANDARD_TWO, nvl(OIT.DEPT_DISTINGUISH_THREE,'0') DEPT_DISTINGUISH_THREE FROM ORG_INFO OI,(select * from ORG_INFO_TUSE OIT5 where OIT5.RESUME_NO= ( SELECT CASE WHEN (select COUNT(0) from ORG_INFO_TUSE OIT2 where OIT2.RESUME_NO=pkg_resume_process.GET_HISTORY_RESUME_NO(#interCpnyID#, #DATE#)) >0 THEN OIT3.RESUME_NO ELSE (SELECT max(RESUME_NO) from ORG_INFO_TUSE OIT4 ) END FROM ORG_INFO_TUSE OIT3 WHERE ROWNUM =1 )
) OIT WHERE OI.RESUME_NO = pkg_resume_process.GET_HISTORY_RESUME_NO(#interCpnyID#, #DATE#) AND OI.ACTIVITY = '1' AND OI.DEPTNO=OIT.DEPTNO (+)
) T WHERE T.CPNY_ID = #interCpnyID#
START WITH T.PARENT_DEPT_NO = '0' CONNECT BY PRIOR T.DEPTNO = T.PARENT_DEPT_NO ORDER SIBLINGS BY T.ORDERNO
